    vachanaMeaningKn: 'ಮನಸ್ಸಿನಲ್ಲಿ ಕಪಟವಿಟ್ಟುಕೊಂಡು ಹೊರಗೆ ಧಾರ್ಮಿಕ ಮುಖವಾಡ ಧರಿಸುವುದನ್ನು ಬಿಟ್ಟು, ನೇರವಾಗಿ ನಡೆದು ಸತ್ಯವನ್ನೇ ನುಡಿಯಬೇಕು.',
    vachanaMeaningEn: 'What use is anointing the forehead when the heart harbors deceit? Walk straight and speak the truth, says Chowdaiah the ferryman.',
    descKn: 'ನಾವಿಕ ಕಾಯಕದ ನಿಷ್ಠುರ ವಚನಕಾರ. ತನ್ನ ಹೆಸರನ್ನೇ ಅಂಕಿತನಾಮವಾಗಿಸಿಕೊಂಡು ಕಪಟ ಆಚಾರಗಳನ್ನು ಕಟುವಾಗಿ ವಿರೋಧಿಸಿದ ನೈಜ ಸುಧಾರಕ.',
    descEn: 'Ferryman by vocation and fearless critic of religious posturing who used his own name as his poetic signature.',
