    vachanaMeaningKn: 'ದೇಹದ ಲಕ್ಷಣಗಳನ್ನು ನೋಡಿ ಹೆಣ್ಣು-ಗಂಡು ಎನ್ನುತ್ತಾರೆ, ಆದರೆ ಒಳಗಿರುವ ಆತ್ಮಕ್ಕೆ ಯಾವುದೇ ಲಿಂಗಭೇದವಿಲ್ಲ.',
    vachanaMeaningEn: 'Breasts and long hair make a woman; beard and mustache make a man. But the soul within is neither woman nor man, O Ramanatha.',
    descKn: 'ಬಸವಪೂರ್ವ ಯುಗದ ಆದ್ಯ ವಚನಕಾರ. ನೇಯ್ಗೆ ಕಾಯಕ ಮಾಡುತ್ತಾ ಆಧ್ಯಾತ್ಮಿಕ ಸಮಾನತೆಯ ಅತ್ಯಂತ ಕ್ರಾಂತಿಕಾರಿ ವಚನಗಳನ್ನು ರಚಿಸಿದರು.',
