    vachanaMeaningKn: 'ಹುಟ್ಟಿನಿಂದ ಯಾರೂ ಮೇಲಲ್ಲ ಅಥವಾ ಕೀಳಲ್ಲ; ಪ್ರಾಮಾಣಿಕ ಕಾಯಕ ಹಾಗೂ ಸದಾಚಾರವೇ ಶ್ರೇಷ್ಠತೆಯ ಮಾನದಂಡ.',
    vachanaMeaningEn: 'You quarrel over high and low caste, do you know the root of caste? One who beholds the Divine in sincere labor is the truly noble soul.',
    descKn: 'ಬಸವಣ್ಣನವರಿಂದಲೇ ಪೂಜ್ಯಭಾವದಿಂದ ಗೌರವಿಸಲ್ಪಟ್ಟ ಹಿರಿಯ ಶರಣ. ಜಾತಿ ವ್ಯವಸ್ಥೆಯ ಕಂದಕವನ್ನು ವಚನಗಳ ಮೂಲಕ ಮುರಿದ ಮಹಾತ್ಮ.',
