    vachanaMeaningKn: 'ಪ್ರಾಮಾಣಿಕ ಕಾಯಕದಲ್ಲಿ ತೊಡಗಿದಾಗ ಆ ಕೆಲಸವೇ ಸಾಕ್ಷಾತ್ ಈಶ್ವರನ ಆರಾಧನೆಯಾಗಿರುತ್ತದೆ.',
    vachanaMeaningEn: 'When absorbed in work, one may forget even meeting the Master or performing rites, for labor itself is Heaven.',
    descKn: 'ಬೀದಿಯಲ್ಲಿ ಚೆಲ್ಲಿದ ಭತ್ತದ ಕಾಳುಗಳನ್ನು ಆಯ್ದು ಜೀವನ ಸಾಗಿಸುತ್ತಿದ್ದ ಶರಣ. ದುರಾಸೆಯಿಲ್ಲದ ಕಾಯಕ ತತ್ತ್ವದ ಶ್ರೇಷ್ಠ ಮಾದರಿ.',
